import { ArrowLeft, Clock3, ShieldAlert, ShieldCheck } from "lucide-react";
import { AppShell } from "@/components/AppShell";
import { useSwapDesk } from "@/store/swapdesk";

const steps = [
  {
    t: "14:02:11.204",
