export const metadata: Metadata = pageMetadata({
  title: "Mission Control",
  description:
    "Monitor autonomous support performance, policy safety, and live SwapDesk agent executions in real time.",
  path: "/",
});

export default function MissionControlPage() {
  return <MissionControl />;
}

import type { MetadataRoute } from "next";
import { SITE_URL } from "@/lib/seo";

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      {
        userAgent: "*",
        allow: "/",
      },
    ],
    sitemap: `${SITE_URL}/sitemap.xml`,
    host: SITE_URL,
  };
}

import type { MetadataRoute } from "next";
import { SITE_URL } from "@/lib/seo";

const routes: Array<{ path: string; priority: number }> = [
  { path: "", priority: 1 },
  { path: "/inbox", priority: 0.8 },
  { path: "/traces", priority: 0.6 },
  { path: "/inventory", priority: 0.7 },
  { path: "/integrations", priority: 0.7 },
  { path: "/simulate", priority: 0.6 },
  { path: "/database", priority: 0.5 },
  { path: "/settings", priority: 0.5 },
];

export default function sitemap(): MetadataRoute.Sitemap {
  const lastModified = new Date();
  return routes.map(({ path, priority }) => ({
    url: `${SITE_URL}${path}`,
    lastModified,
    changeFrequency: "weekly",
    priority,
  }));
}

